# процесс Temporal — надёжен по построению, повторы бесплатны
@workflow.defn
class ResearchAgent:
    @workflow.run
    async def run(self, task):
        plan = await workflow.execute_activity(make_plan, task)
        for step in plan.steps:           # каждая активность — контрольная точка
            await workflow.execute_activity(do_step, step)
